namespace UA.Facade.Implementation.Admission;
public sealed class AdmissionFacade(IRepository<AdmissionCircular> circulars,IRepository<CircularSeat> seats,
 IRepository<Department> departments,IRepository<Applicant> applicants,IRepository<Application> applications,
 IRepository<UserAccount> users,IRepository<Role> roles,IRepository<UserRole> assignments,IRepository<AcademicTerm> terms,
 IRepository<FeeType> rates,IRepository<Due> dues,IRepository<Payment> payments,IRepository<PaymentAllocation> allocations,
 IRepository<Batch> batches,IRepository<Section> sections,IRepository<CurriculumCourse> curriculum,IRepository<Course> courses,
 IRepository<Offering> offerings,IRepository<Enrollment> enrollments,IRepository<UA.Entities.Student> students,
 IRepository<ApprovalRecord> approvals,IRepository<UploadedDocument> documents,IUnitOfWork work,IUserAccessFacade access,
 ICurrentUser current,IClock clock,IPasswordHasher passwords,IPasswordPolicy policy,IFeeCalculator calculator,
 IApplicantStorage uploads,IFileStorage files,IStudentRecordCreator creator,IManualAuditService audit,IRepository<NotificationTemplate> templates,IRepository<Notification> notifications) : IAdmissionFacade
{
 private int Actor=>current.UserId??throw new ForbiddenException();
 private static string Required(string? text,int max){if(string.IsNullOrWhiteSpace(text)||text.Trim().Length>max)throw new BusinessRuleException("Required field missing or too long.");return text.Trim();}
 private async Task<AdmissionCircular> Circular(int id)=>await circulars.FirstAsync(x=>x.CircularId==id)??throw new NotFoundException();
 private async Task<Application> ApplicationById(int id)=>await applications.FirstAsync(x=>x.ApplicationId==id)??throw new NotFoundException();
 private async Task<Applicant> Person(int id)=>await applicants.FirstAsync(x=>x.ApplicantId==id)??throw new NotFoundException();
 private async Task<UserAccount> ApplicantAccount(){var u=await users.FirstAsync(x=>x.UserId==Actor&&x.Status=="Active")??throw new ForbiddenException();if(!(await access.ForUserAsync(Actor)).Assignments.Any(x=>x.RoleName==RoleNames.Applicant))throw new ForbiddenException("Applicant account required.");return u;}
 private async Task<Application> Authorize(int id,bool staff,string permission="applications.review") {var a=await ApplicationById(id);if(staff)await access.RequireGlobalAsync(permission);else {await ApplicantAccount();if((await Person(a.ApplicantId)).UserId!=Actor)throw new ForbiddenException();}return a;}
 private async Task Notify(int userId,string code,string eventKey,CancellationToken ct){var t=await templates.FirstAsync(x=>x.Code==code&&x.IsActive,ct);if(t==null)return;if(await notifications.FirstAsync(x=>x.RecipientUserId==userId&&x.EventKey==eventKey,ct)==null)await notifications.AddAsync(new Notification{RecipientUserId=userId,TemplateId=t.TemplateId,EventKey=eventKey,Status="Queued",QueuedAt=clock.Now},ct);}
 private async Task<AcademicTerm> Term(AdmissionCircular c)=>await terms.FirstAsync(x=>x.Year==c.IntakeYear&&x.TermNo==1)??throw new BusinessRuleException("Configure the intake's January academic term first.");
 public async Task<IReadOnlyList<AdmissionSeat>> DepartmentsAsync()=>(await departments.ListAsync(x=>x.Status=="Active")).Select(x=>new AdmissionSeat(x.DepartmentId,x.Name,120)).ToArray();
 public async Task<IReadOnlyList<CircularRow>> CircularsAsync(bool staff=false){if(staff)await access.RequireGlobalAsync("circulars.manage");var ds=await departments.ListAsync();var cs=await circulars.ListAsync(x=>staff||x.Status=="Published"||x.Status=="Closed");var ids=cs.Select(x=>x.CircularId).ToArray();var ss=await seats.ListAsync(x=>ids.Contains(x.CircularId));return cs.OrderByDescending(x=>x.IntakeYear).Select(c=>new CircularRow(c.CircularId,c.IntakeYear,c.ApplicationOpen,c.ApplicationClose,c.TestDate,c.TestVenue,c.ResultDate,c.EnrollmentDeadline,c.Status,ss.Where(s=>s.CircularId==c.CircularId).Select(s=>new AdmissionSeat(s.DepartmentId,ds.Single(d=>d.DepartmentId==s.DepartmentId).Name,s.Seats)).ToArray())).ToArray();}
 public async Task CreateCircularAsync(CircularInput i){await access.RequireGlobalAsync("circulars.manage");if(i.Year<2000||i.Year>2100||i.Open.Date>i.Close.Date||i.Close.Date>=i.Test.Date||i.Test.Date>i.Result.Date||i.Result.Date>i.Deadline.Date)throw new BusinessRuleException("Invalid intake or date order.");var venue=Required(i.Venue,150);if(i.DepartmentIds is null||i.Seats is null||i.DepartmentIds.Length==0||i.DepartmentIds.Length!=i.Seats.Length||i.DepartmentIds.Distinct().Count()!=i.DepartmentIds.Length||i.Seats.Any(s=>s<1||s>999))throw new BusinessRuleException("Provide unique departments and positive seat counts.");await work.ExecuteTransactionAsync(async ct=>{if(await circulars.FirstAsync(x=>x.IntakeYear==i.Year,ct)!=null)throw new BusinessRuleException("Intake already exists.");var valid=await departments.ListAsync(x=>x.Status=="Active",ct);if(i.DepartmentIds.Any(id=>valid.All(d=>d.DepartmentId!=id)))throw new BusinessRuleException("Invalid department.");var c=new AdmissionCircular{IntakeYear=i.Year,ApplicationOpen=i.Open.Date,ApplicationClose=i.Close.Date,TestDate=i.Test.Date,TestVenue=venue,ResultDate=i.Result.Date,EnrollmentDeadline=i.Deadline.Date,Status="Draft"};await circulars.AddAsync(c,ct);await work.SaveChangesAsync(ct);for(int n=0;n<i.Seats.Length;n++)await seats.AddAsync(new CircularSeat{CircularId=c.CircularId,DepartmentId=i.DepartmentIds[n],Seats=i.Seats[n]},ct);});}
 public async Task PublishCircularAsync(int id){await access.RequireGlobalAsync("circulars.manage");await work.ExecuteTransactionAsync(async ct=>{var c=await Circular(id);if(c.Status!="Draft"||c.ApplicationClose<clock.Today)throw new BusinessRuleException("Only a current draft can be published.");await Term(c);c.Status="Published";});}
 public async Task UpdateCircularAsync(int id,DateTime close,DateTime test,string venue,DateTime result,DateTime deadline,string reason)
 {await access.RequireGlobalAsync("circulars.manage");venue=Required(venue,150);reason=Required(reason,255);await work.ExecuteTransactionAsync(async ct=>{
  var c=await Circular(id);var aa=await applications.ListAsync(x=>x.CircularId==id,ct);
  if(close.Date<c.ApplicationOpen||close.Date>=test.Date||test.Date>result.Date||result.Date>deadline.Date)throw new BusinessRuleException("Invalid date order.");
  if(c.Status!="Draft"&&(close.Date<c.ApplicationClose||deadline.Date<c.EnrollmentDeadline))throw new BusinessRuleException("Published deadlines may only be extended; close applications explicitly if needed.");
  if(aa.Any(x=>x.TestMarks!=null||x.MeritRank!=null)&&(test.Date!=c.TestDate||venue!=c.TestVenue))throw new BusinessRuleException("Test date and venue are locked after importing results.");
  if(aa.Any(x=>x.ApplicationStatus is "Result published" or "Enrolled")&&result.Date!=c.ResultDate)throw new BusinessRuleException("Published result date is locked.");
  if(c.Status!="Draft"&&test.Date!=c.TestDate&&test.Date<clock.Today)throw new BusinessRuleException("New test date must not be in the past.");
  var oldClose=c.ApplicationClose;var oldDeadline=c.EnrollmentDeadline;c.ApplicationClose=close.Date;c.TestDate=test.Date;c.TestVenue=venue;c.ResultDate=result.Date;c.EnrollmentDeadline=deadline.Date;
  if(aa.Count>0){var term=await Term(c);var ids=aa.Select(x=>x.ApplicantId).ToArray();var dd=await dues.ListAsync(x=>x.ApplicantId!=null&&ids.Contains(x.ApplicantId.Value)&&x.TermId==term.TermId&&x.StudentId==null&&(x.Status=="Unpaid"||x.Status=="Partially paid"),ct);
  var feeIds=dd.Select(x=>x.FeeTypeId).Distinct().ToArray();var rr=await rates.ListAsync(x=>feeIds.Contains(x.FeeTypeId),ct);
  foreach(var d in dd){var fee=rr.Single(x=>x.FeeTypeId==d.FeeTypeId).Name;if(fee=="Application"&&d.DueDate==oldClose)d.DueDate=close.Date;else if((fee==FeeNames.Registration||fee==FeeNames.Tuition)&&d.DueDate==oldDeadline)d.DueDate=deadline.Date;}}
  await audit.LogAsync("Circular revision","AdmissionCircular",id.ToString(),reason);
 });}
 public async Task CloseCircularAsync(int id,string reason){await access.RequireGlobalAsync("circulars.manage");reason=Required(reason,255);await work.ExecuteTransactionAsync(async ct=>{var c=await Circular(id);if(c.Status!="Published")throw new BusinessRuleException("Only published circulars can be closed.");c.Status="Closed";await audit.LogAsync("Close applications","AdmissionCircular",id.ToString(),reason);});}
 public async Task RegisterAsync(string email,string password,string mobile){email=Required(email,50).ToLowerInvariant();mobile=Required(mobile,20);if(!System.Net.Mail.MailAddress.TryCreate(email,out var address)||address.Address!=email||!mobile.All(c=>char.IsAsciiDigit(c)||c=='+')||mobile.Length<7)throw new BusinessRuleException("Invalid email or phone.");if(password is null||password.Length>128)throw new BusinessRuleException("Invalid password length.");if(policy.Validate(password) is string issue)throw new BusinessRuleException(issue);await work.ExecuteTransactionAsync(async ct=>{if(await users.FirstAsync(x=>x.Email==email||x.Username==email,ct)!=null)throw new BusinessRuleException("Account already exists; use sign in or password reset.");var r=await roles.FirstAsync(x=>x.Name==RoleNames.Applicant,ct)??throw new BusinessRuleException("Applicant role missing; run initialization.");var u=new UserAccount{Username=email,Email=email,Mobile=mobile,PasswordHash=passwords.Hash(password),Status="Active",IsVerified=false};await users.AddAsync(u,ct);await assignments.AddAsync(new UserRole{User=u,RoleId=r.RoleId},ct);});}
 private async Task AddDue(int applicant,int department,int termId,DateTime rateDate,string name,decimal quantity,DateTime deadline,CancellationToken ct){var rr=await rates.ListAsync(x=>x.DepartmentId==department,ct);var ids=rr.Where(x=>x.Name==name).Select(x=>x.FeeTypeId).ToArray();if(await dues.FirstAsync(x=>x.ApplicantId==applicant&&x.TermId==termId&&ids.Contains(x.FeeTypeId),ct)!=null)return;var r=calculator.Rate(rr,name,rateDate);var amount=calculator.Calculate(r.Amount,quantity);await dues.AddAsync(new Due{ApplicantId=applicant,FeeTypeId=r.FeeTypeId,TermId=termId,Amount=amount,DueDate=deadline,Status=amount==0?"Paid":"Unpaid"},ct);}
 public async Task<int> ApplyAsync(int circularId,int departmentId,ApplicantInput i,byte[] photo,string mime,byte[]? certificate){var u=await ApplicantAccount();if(!u.IsVerified)throw new BusinessRuleException("Verify your email before applying.");if(!i.Consent||i.Birth.Date>=clock.Today||i.Birth.Year<1900||i.SscGpa<0||i.SscGpa>5||i.HscGpa<0||i.HscGpa>5||i.SscGpa!=decimal.Round(i.SscGpa,2)||i.HscGpa!=decimal.Round(i.HscGpa,2)||i.Gender is not ("Male" or "Female" or "Other"))throw new BusinessRuleException("Invalid profile, GPA or consent.");var name=Required(i.Name,100);var address=Required(i.Address,255);var guardian=Required(i.Guardian,100);var phone=Required(i.GuardianPhone,20);if(phone.Length<7||!phone.All(c=>char.IsAsciiDigit(c)||c=='+'))throw new BusinessRuleException("Enter a valid guardian phone number.");var sb=Required(i.SscBoard,30).ToUpperInvariant();var sr=Required(i.SscRoll,20).ToUpperInvariant();var hb=Required(i.HscBoard,30).ToUpperInvariant();var hr=Required(i.HscRoll,20).ToUpperInvariant();if(mime is not ("image/png" or "image/jpeg"))throw new BusinessRuleException("A JPEG or PNG photo is required.");string? path=null,cert=null;int id=0;try{path=await uploads.SaveApplicantAsync(photo,mime);if(certificate!=null)cert=await uploads.SaveApplicantAsync(certificate,"application/pdf");await work.ExecuteTransactionAsync(async ct=>{var c=await Circular(circularId);if(c.Status!="Published"||clock.Today<c.ApplicationOpen||clock.Today>c.ApplicationClose||await seats.FirstAsync(x=>x.CircularId==circularId&&x.DepartmentId==departmentId,ct)==null)throw new BusinessRuleException("Application window or department unavailable.");var term=await Term(c);var p=await applicants.FirstAsync(x=>x.UserId==u.UserId,ct);var same=await applicants.ListAsync(x=>x.UserId!=u.UserId&&((x.SscBoard==sb&&x.SscRoll==sr)||(x.HscBoard==hb&&x.HscRoll==hr)),ct);if(same.Count>0)throw new BusinessRuleException("Education identity already registered; contact admissions.");if(p!=null&&(p.SscBoard!=sb||p.SscRoll!=sr||p.HscBoard!=hb||p.HscRoll!=hr))throw new BusinessRuleException("Education identity changes require staff review.");if(p==null){p=new Applicant{UserId=u.UserId,FullName=name,DateOfBirth=i.Birth.Date,Gender=i.Gender,Address=address,GuardianName=guardian,GuardianPhone=phone,SscBoard=sb,SscRoll=sr,SscResult=i.SscGpa,HscBoard=hb,HscRoll=hr,HscResult=i.HscGpa,PhotoPath=path!};await applicants.AddAsync(p,ct);await work.SaveChangesAsync(ct);}else if(p.DateOfBirth!=i.Birth.Date)throw new BusinessRuleException("Birth date changes require staff review.");if(await applications.FirstAsync(x=>x.ApplicantId==p.ApplicantId&&x.CircularId==circularId,ct)!=null)throw new BusinessRuleException("One application per intake is allowed.");var a=new Application{ApplicantId=p.ApplicantId,CircularId=circularId,DepartmentId=departmentId,ApplicationStatus="Submitted",SubmittedAt=clock.Now};await applications.AddAsync(a,ct);p.PhotoPath=path!;await documents.AddAsync(new UploadedDocument{ApplicantId=p.ApplicantId,DocumentType="Photo",FilePath=path!,MimeType=mime,FileSizeKb=(photo.Length+1023)/1024,UploadedAt=clock.Now},ct);if(cert!=null)await documents.AddAsync(new UploadedDocument{ApplicantId=p.ApplicantId,DocumentType="Certificate",FilePath=cert,MimeType="application/pdf",FileSizeKb=(certificate!.Length+1023)/1024,UploadedAt=clock.Now},ct);await AddDue(p.ApplicantId,departmentId,term.TermId,term.StartDate,"Application",1,c.ApplicationClose,ct);await work.SaveChangesAsync(ct);id=a.ApplicationId;await audit.LogAsync("Consent","Application",id.ToString(),"Admission data-use consent accepted");await Notify(u.UserId,"admission.submitted",$"admission.submitted:{id}",ct);});return id;}catch{if(path!=null)await uploads.DeleteApplicantAsync(path);if(cert!=null)await uploads.DeleteApplicantAsync(cert);throw;}}
 private async Task<AdmissionInvoice> Invoice(Application a){var p=await Person(a.ApplicantId);var c=await Circular(a.CircularId);var t=await Term(c);var rr=await rates.ListAsync(x=>x.DepartmentId==a.DepartmentId);var ids=rr.Select(x=>x.FeeTypeId).ToArray();var dd=await dues.ListAsync(x=>x.ApplicantId==a.ApplicantId&&x.TermId==t.TermId&&ids.Contains(x.FeeTypeId)&&x.EnrollmentId==null);var did=dd.Select(x=>x.DueId).ToArray();var aa=await allocations.ListAsync(x=>did.Contains(x.DueId));var pids=aa.Select(x=>x.PaymentId).Distinct().ToArray();var pp=await payments.ListAsync(x=>pids.Contains(x.PaymentId)&&x.ApplicantId==a.ApplicantId&&x.Status=="Successful"&&x.ReversesPaymentId==null);var ok=pp.Select(x=>x.PaymentId).ToArray();var reversed=await payments.ListAsync(x=>x.ReversesPaymentId!=null&&ok.Contains(x.ReversesPaymentId.Value)&&x.Status=="Successful");var valid=ok.Except(reversed.Select(x=>x.ReversesPaymentId!.Value)).ToHashSet();return new(a.ApplicationId,p.ApplicantId,p.FullName,c.IntakeYear,dd.Select(d=>new InvoiceLine(d.DueId,rr.Single(r=>r.FeeTypeId==d.FeeTypeId).Name,d.Amount,aa.Where(x=>x.DueId==d.DueId&&valid.Contains(x.PaymentId)).Sum(x=>x.Amount),d.DueDate,d.Status)).OrderBy(x=>x.DueId).ToArray());}
 private static bool Cleared(AdmissionInvoice i,string fee)=>i.Lines.Any(x=>x.Fee==fee)&&i.Lines.Where(x=>x.Fee==fee).All(x=>x.Status!="Reversed"&&x.Paid>=x.Amount);
 public async Task<AdmissionInvoice> InvoiceAsync(int id,bool staff=false)=>await Invoice(await Authorize(id,staff));
 public async Task<IReadOnlyList<AdmissionRow>> ApplicationsAsync(int? circularId=null,bool staff=false){if(staff)await access.RequireGlobalAsync("applications.review");else await ApplicantAccount();var p=staff?null:await applicants.FirstAsync(x=>x.UserId==Actor);if(!staff&&p==null)return [];var ownId=p?.ApplicantId??0;var aa=await applications.ListAsync(x=>(staff||x.ApplicantId==ownId)&&(circularId==null||x.CircularId==circularId));var ds=await departments.ListAsync();var rows=new List<AdmissionRow>();foreach(var a in aa.OrderBy(x=>x.DepartmentId).ThenBy(x=>x.MeritRank??int.MaxValue)){var inv=await Invoice(a);bool paid=Cleared(inv,"Application");bool published=a.ApplicationStatus is "Result published" or "Enrolled";rows.Add(new(a.ApplicationId,a.ApplicantId,a.CircularId,a.DepartmentId,inv.Name,ds.Single(d=>d.DepartmentId==a.DepartmentId).Name,a.ApplicationStatus=="Submitted"&&paid?"Paid":a.ApplicationStatus,staff||published?a.TestMarks:null,staff||published?a.MeritRank:null,staff||published?a.SelectionStatus:null,a.DocumentsVerified,paid,Cleared(inv,FeeNames.Registration)&&Cleared(inv,FeeNames.Tuition)));}return rows;}
 public async Task CreateEnrollmentInvoiceAsync(int id){var a=await Authorize(id,false);await work.ExecuteTransactionAsync(async ct=>{var c=await Circular(a.CircularId);if(a.ApplicationStatus!="Result published"||a.SelectionStatus is not ("Selected" or "Replacement")||clock.Today>c.EnrollmentDeadline||!Cleared(await Invoice(a),"Application"))throw new BusinessRuleException("A selected, fee-cleared applicant within the enrollment window is required.");var t=await Term(c);var b=await batches.FirstAsync(x=>x.AdmissionYear==c.IntakeYear&&x.DepartmentId==a.DepartmentId,ct)??throw new BusinessRuleException("Prepare the intake batch and curriculum.");var cc=(await curriculum.ListAsync(x=>x.CurriculumId==b.CurriculumId&&x.SemesterNo==1,ct)).Select(x=>x.CourseId).ToArray();var credits=(await courses.ListAsync(x=>cc.Contains(x.CourseId),ct)).Sum(x=>x.Credits);if(credits<=0)throw new BusinessRuleException("Semester-one curriculum is missing.");await AddDue(a.ApplicantId,a.DepartmentId,t.TermId,t.StartDate,FeeNames.Registration,1,c.EnrollmentDeadline,ct);await AddDue(a.ApplicantId,a.DepartmentId,t.TermId,t.StartDate,FeeNames.Tuition,credits,c.EnrollmentDeadline,ct);});}
 public async Task<AdmitCardInfo> AdmitCardAsync(int id){var a=await Authorize(id,false);var i=await Invoice(a);if(!Cleared(i,"Application"))throw new BusinessRuleException("Admit card requires confirmed application payment.");var c=await Circular(a.CircularId);var d=await departments.FirstAsync(x=>x.DepartmentId==a.DepartmentId)??throw new NotFoundException();return new(a.ApplicantId,i.Name,d.Name,c.TestDate,c.TestVenue);}
 public async Task<(byte[] Data,string Mime)> PhotoAsync(int id,bool staff=false){var a=await Authorize(id,staff);var p=await Person(a.ApplicantId);await audit.LogAsync("Download","Applicant",p.ApplicantId.ToString(),"Photo");return(await files.ReadAsync(p.PhotoPath),p.PhotoPath.EndsWith(".png")?"image/png":"image/jpeg");}
 public async Task<IReadOnlyList<ApplicantDocumentRow>> DocumentsAsync(int id,bool staff=false){var a=await Authorize(id,staff);return (await documents.ListAsync(x=>x.ApplicantId==a.ApplicantId)).Select(x=>new ApplicantDocumentRow(x.DocumentId,x.DocumentType,x.MimeType)).ToArray();}
 public async Task<(byte[] Data,string Mime)> DocumentAsync(int id,int documentId,bool staff=false){var a=await Authorize(id,staff);var d=await documents.FirstAsync(x=>x.DocumentId==documentId&&x.ApplicantId==a.ApplicantId)??throw new NotFoundException();await audit.LogAsync("Download","UploadedDocument",documentId.ToString());return(await files.ReadAsync(d.FilePath),d.MimeType);}
 public async Task<IReadOnlyList<string>> ImportResultsAsync(int circularId,IReadOnlyList<TestResultInput> rows){await access.RequireGlobalAsync("merit.manage");var errors=new List<string>();await work.ExecuteTransactionAsync(async ct=>{var c=await Circular(circularId);if(c.Status is not ("Published" or "Closed")||clock.Today<c.TestDate)throw new BusinessRuleException("Test not held or circular unavailable.");var aa=await applications.ListAsync(x=>x.CircularId==circularId,ct);if(aa.Any(x=>x.ApplicationStatus is "Result published" or "Enrolled"))throw new BusinessRuleException("Published results are locked.");if(rows.Count==0)errors.Add("No result rows.");var staged=new List<(Application App,TestResultInput Row)>();foreach(var row in rows){var a=aa.SingleOrDefault(x=>x.ApplicantId==row.ApplicantId);if(a==null||row.Rank<1||row.Marks<0||row.Marks>9999.99m||row.Marks!=decimal.Round(row.Marks,2)||rows.Count(x=>x.ApplicantId==row.ApplicantId)>1){errors.Add($"Row {row.Line}: invalid applicant, marks, rank or duplicate.");continue;}if(!Cleared(await Invoice(a),"Application")){errors.Add($"Row {row.Line}: application fee not confirmed.");continue;}staged.Add((a,row));}var combined=aa.Where(a=>staged.All(s=>s.App.ApplicationId!=a.ApplicationId)&&a.MeritRank.HasValue).Select(a=>(a.DepartmentId,Rank:a.MeritRank!.Value)).Concat(staged.Select(s=>(s.App.DepartmentId,s.Row.Rank)));if(combined.GroupBy(x=>x).Any(g=>g.Count()>1))errors.Add("Duplicate department merit rank.");if(errors.Count>0)return;foreach(var s in staged){s.App.TestMarks=s.Row.Marks;s.App.MeritRank=s.Row.Rank;}});return errors;}
 public async Task PublishMeritAsync(int circularId){await access.RequireGlobalAsync("merit.manage");await work.ExecuteTransactionAsync(async ct=>{var c=await Circular(circularId);if(c.Status is not ("Published" or "Closed")||clock.Today<c.ResultDate)throw new BusinessRuleException("Result publication date has not arrived or circular unavailable.");var aa=await applications.ListAsync(x=>x.CircularId==circularId,ct);if(aa.Any(x=>x.ApplicationStatus is "Result published" or "Enrolled"))throw new BusinessRuleException("Results already published.");var ss=await seats.ListAsync(x=>x.CircularId==circularId,ct);if(!aa.Any(x=>x.MeritRank.HasValue&&x.TestMarks.HasValue))throw new BusinessRuleException("Import results first.");foreach(var seat in ss){var ranked=aa.Where(x=>x.DepartmentId==seat.DepartmentId&&x.MeritRank.HasValue&&x.TestMarks.HasValue).OrderBy(x=>x.MeritRank).ToArray();if(ranked.GroupBy(x=>x.MeritRank).Any(g=>g.Count()>1))throw new BusinessRuleException("Duplicate merit ranks.");for(int n=0;n<ranked.Length;n++){var a=ranked[n];if(!Cleared(await Invoice(a),"Application"))throw new BusinessRuleException("Ranked applicant has unpaid application fee.");a.SelectionStatus=n<seat.Seats?"Selected":"Not selected";a.ApplicationStatus="Result published";await Notify((await Person(a.ApplicantId)).UserId,"admission.result",$"admission.result:{a.ApplicationId}",ct);}}});}
 public async Task VerifyDocumentsAsync(int id){var a=await Authorize(id,true);if(a.ApplicationStatus!="Result published"||a.SelectionStatus is not ("Selected" or "Replacement"))throw new BusinessRuleException("Selected applicant required.");a.DocumentsVerified=true;await work.SaveChangesAsync();}
 public async Task<StudentCreatedCredential> ConfirmAsync(int id){await access.RequireGlobalAsync("enrollment.confirm");StudentCreatedCredential? output=null;await work.ExecuteTransactionAsync(async ct=>{var a=await ApplicationById(id);var c=await Circular(a.CircularId);var inv=await Invoice(a);if(a.ApplicationStatus!="Result published"||a.SelectionStatus is not ("Selected" or "Replacement")||!a.DocumentsVerified||clock.Today>c.EnrollmentDeadline||!Cleared(inv,"Application")||!Cleared(inv,FeeNames.Registration)||!Cleared(inv,FeeNames.Tuition))throw new BusinessRuleException("Enrollment requires verified documents and confirmed application and first-semester fees within the deadline.");var p=await Person(a.ApplicantId);var u=await users.FirstAsync(x=>x.UserId==p.UserId,ct)??throw new NotFoundException();var b=await batches.FirstAsync(x=>x.AdmissionYear==c.IntakeYear&&x.DepartmentId==a.DepartmentId,ct)??throw new BusinessRuleException("Intake batch missing.");var ss=await sections.ListAsync(x=>x.BatchId==b.BatchId,ct);var existing=await students.ListAsync(x=>x.AdmissionBatchId==b.BatchId,ct);var seat=await seats.FirstAsync(x=>x.CircularId==c.CircularId&&x.DepartmentId==a.DepartmentId,ct)??throw new BusinessRuleException("Seat configuration missing.");var ranked=(await applications.ListAsync(x=>x.CircularId==c.CircularId&&x.DepartmentId==a.DepartmentId&&x.MeritRank!=null,ct)).OrderBy(x=>x.MeritRank).ToArray();int roll=a.SelectionStatus=="Replacement"?Enumerable.Range(1,Math.Min(b.SeatLimit,seat.Seats)).FirstOrDefault(n=>existing.All(s=>s.RollNo!=n)&&ranked.Take(seat.Seats).Where(x=>x.SelectionStatus=="Selected"&&x.ApplicationStatus!="Enrolled").All(x=>Array.IndexOf(ranked,x)+1!=n)):Array.FindIndex(ranked,x=>x.ApplicationId==a.ApplicationId)+1;if(roll<1||roll>seat.Seats||roll>b.SeatLimit||existing.Any(s=>s.RollNo==roll))throw new BusinessRuleException("No available merit roll.");int offset=roll;Section? section=null;foreach(var s in ss.OrderBy(x=>x.Name).ThenBy(x=>x.SectionId)){if(offset<=s.Capacity){section=s;break;}offset-=s.Capacity;}if(section==null||existing.Count(s=>s.SectionId==section.SectionId)>=section.Capacity)throw new BusinessRuleException("Prepare section capacity.");var t=await Term(c);var links=(await curriculum.ListAsync(x=>x.CurriculumId==b.CurriculumId&&x.SemesterNo==1,ct)).Select(x=>x.CourseId).ToArray();if(links.Length==0)throw new BusinessRuleException("Missing first-semester curriculum.");var off=await offerings.ListAsync(x=>x.BatchId==b.BatchId&&x.SectionId==section.SectionId&&x.TermId==t.TermId&&x.SemesterNo==1&&!x.IsSpecialRetake&&x.Status!="Cancelled",ct);if(links.Any(k=>off.Count(x=>x.CourseId==k)!=1))throw new BusinessRuleException("Generate semester-one offerings first.");output=await creator.AddAsync(new(a.ApplicationId,a.DepartmentId,b.BatchId,section.SectionId,(short)roll,p.FullName,p.DateOfBirth,p.Gender,p.GuardianName,p.GuardianPhone,u.Mobile??p.GuardianPhone,p.Address,null),Actor,ct);await work.SaveChangesAsync(ct);var student=await students.FirstAsync(x=>x.StudentId==output.StudentId,ct)??throw new NotFoundException();student.PhotoPath=p.PhotoPath;foreach(var o in off.Where(x=>links.Contains(x.CourseId)))await enrollments.AddAsync(new Enrollment{StudentId=student.StudentId,OfferingId=o.OfferingId,EnrollmentType="Regular",AttemptNo=1,Status="Registered"},ct);var did=inv.Lines.Select(x=>x.DueId).ToArray();foreach(var d in await dues.ListAsync(x=>did.Contains(x.DueId),ct)){d.StudentId=student.StudentId;if(inv.Lines.Single(x=>x.DueId==d.DueId).Paid>=d.Amount&&d.Status!="Reversed")d.Status="Paid";}var pid=(await allocations.ListAsync(x=>did.Contains(x.DueId),ct)).Select(x=>x.PaymentId).Distinct().ToArray();if((await allocations.ListAsync(x=>pid.Contains(x.PaymentId),ct)).Any(x=>!did.Contains(x.DueId)))throw new BusinessRuleException("A payment spans other applications; reconcile ownership before enrollment.");foreach(var pay in await payments.ListAsync(x=>pid.Contains(x.PaymentId)&&x.ApplicantId==p.ApplicantId&&x.Status=="Successful",ct)){if(pay.StudentId!=null&&pay.StudentId!=student.StudentId)throw new BusinessRuleException("Payment already transferred.");pay.StudentId=student.StudentId;}foreach(var doc in await documents.ListAsync(x=>x.ApplicantId==p.ApplicantId&&x.StudentId==null&&x.UploadedAt>=a.SubmittedAt.AddSeconds(-1),ct))doc.StudentId=student.StudentId;a.ApplicationStatus="Enrolled";});return output!;}
 public async Task ReplaceAsync(int id,string reference){await access.RequireGlobalAsync("enrollment.replace");reference=Required(reference,30);await work.ExecuteTransactionAsync(async ct=>{var a=await ApplicationById(id);var c=await Circular(a.CircularId);if(a.ApplicationStatus!="Result published"||a.SelectionStatus!="Not selected")throw new BusinessRuleException("Only an unselected published applicant can be considered.");var aa=await applications.ListAsync(x=>x.CircularId==a.CircularId&&x.DepartmentId==a.DepartmentId,ct);var seat=await seats.FirstAsync(x=>x.CircularId==a.CircularId&&x.DepartmentId==a.DepartmentId,ct)??throw new NotFoundException();if(clock.Today>c.EnrollmentDeadline)throw new BusinessRuleException("Enrollment deadline passed; a new authorized window is needed before replacement.");if(aa.Count(x=>x.SelectionStatus is "Selected" or "Replacement")>=seat.Seats)throw new BusinessRuleException("No released seat. Payment-dependent seat release is deferred.");if(aa.Where(x=>x.SelectionStatus=="Not selected").OrderBy(x=>x.MeritRank).FirstOrDefault()?.ApplicationId!=a.ApplicationId)throw new BusinessRuleException("Use next merit applicant.");var dept=await departments.FirstAsync(x=>x.DepartmentId==a.DepartmentId,ct)??throw new NotFoundException();if(!System.Text.RegularExpressions.Regex.IsMatch(reference,"^"+System.Text.RegularExpressions.Regex.Escape(dept.Code)+"-[A-Z0-9]+-[0-9]{4}-[0-9]{4}$"))throw new BusinessRuleException("Use department-TYPE-YYYY-NNNN approval reference.");if(await approvals.FirstAsync(x=>x.ReferenceNo==reference,ct)!=null)throw new BusinessRuleException("Approval reference already used.");var ap=new ApprovalRecord{ReferenceNo=reference,ApprovalType="Replacement",Status="Approved",ApproverId=Actor,ApprovalDate=clock.Now};await approvals.AddAsync(ap,ct);await work.SaveChangesAsync(ct);a.ApprovalId=ap.ApprovalId;a.SelectionStatus="Replacement";});}
 public async Task<AdmissionResultRow?> PublicResultAsync(int applicantId,int year,DateTime birth){var p=await applicants.FirstAsync(x=>x.ApplicantId==applicantId&&x.DateOfBirth==birth.Date&&x.SscBoard!="ANONYMIZED");if(p==null)return null;var c=await circulars.FirstAsync(x=>x.IntakeYear==year&&(x.Status=="Published"||x.Status=="Closed"));if(c==null)return null;var a=await applications.FirstAsync(x=>x.ApplicantId==applicantId&&x.CircularId==c.CircularId&&(x.ApplicationStatus=="Result published"||x.ApplicationStatus=="Enrolled"));if(a?.MeritRank==null||a.TestMarks==null)return null;var d=await departments.FirstAsync(x=>x.DepartmentId==a.DepartmentId);return new(applicantId,year,d?.Name??"",a.MeritRank.Value,a.TestMarks.Value,a.SelectionStatus??"Not selected");}
}
